<template>
  <main class="app-shell">
    <AuthenticatedTopbar :user="user" section="shares" />
    <section class="content-wrap">
      <div class="page-heading"><div><p class="eyebrow">{{ t('shares.eyebrow') }}</p><h1>{{ t('shares.heading') }}</h1><p class="muted">{{ t('shares.copy') }}</p></div><button class="refresh-button" :title="t('shares.refresh')" @click="loadShares"><RefreshCw :size="18" :class="{ spin: loading }" /></button></div>
      <div v-if="error" class="alert error">{{ error }}</div><div v-if="notice" class="alert success">{{ notice }}</div>
      <div class="file-table-wrap share-management-table"><table class="file-table"><thead><tr><th>{{ t('shares.file') }}</th><th>{{ t('shares.token') }}</th><th>{{ t('shares.expiresAt') }}</th><th>{{ t('shares.usage') }}</th><th>{{ t('shares.status') }}</th><th>{{ t('shares.createdAt') }}</th><th></th></tr></thead><tbody><tr v-for="item in shares" :key="item.id"><td><strong class="share-file-name">{{ item.fileName || '-' }}</strong></td><td><code class="share-token" :title="item.token">{{ item.token }}</code></td><td>{{ formatDate(item.expiresAt) }}<small class="share-remaining">{{ remainingLabel(item) }}</small></td><td>{{ item.downloadCount }} / {{ item.maxDownloads || t('shares.unlimited') }}</td><td><span class="status-label" :class="{ disabled: item.status !== 'active' }"><i></i>{{ statusLabel(item.status) }}</span></td><td>{{ formatDate(item.createdAt) }}</td><td><div class="row-actions"><button class="icon-button" :title="t('shares.details')" @click="openDetails(item)"><Eye :size="16" /></button><button class="icon-button" :title="t('shares.copy')" @click="copyShare(item)"><Copy :size="16" /></button><button v-if="item.status !== 'revoked'" class="icon-button danger-icon" :title="t('shares.revoke')" @click="revokeShare(item)"><Trash2 :size="16" /></button></div></td></tr></tbody></table><div v-if="loading" class="empty-state"><LoaderCircle :size="28" class="spin" /><span>{{ t('shares.loading') }}</span></div><div v-else-if="!shares.length" class="empty-state"><Share2 :size="34" /><strong>{{ t('shares.empty') }}</strong><span>{{ t('shares.emptyCopy') }}</span></div></div><div v-if="shareTotal > sharePageSize.value" class="pagination"><button class="secondary-button" :disabled="sharePage === 1" @click="sharePage--; loadShares()">{{ t('common.previous') }}</button><span>{{ t('common.page', { page: sharePage }) }} / {{ shareTotalPages }}</span><button class="secondary-button" :disabled="sharePage * sharePageSize.value >= shareTotal" @click="sharePage++; loadShares()">{{ t('common.next') }}</button><label class="page-size-label">{{ t('common.pageSize') }}<select v-model.number="sharePageSize" @change="changeSharePageSize"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><template v-if="shareTotalPages > 7"><input v-model="sharePageInput" class="jump-input" type="number" min="1" :max="shareTotalPages" :placeholder="t('common.pageInput')" @keyup.enter="jumpSharePage" /><button class="secondary-button" @click="jumpSharePage">{{ t('common.jump') }}</button></template></div>
      <section class="form-panel share-groups-panel"><div class="panel-heading"><div><p class="eyebrow">SHARE GROUPS</p><h2>{{ t('shares.groupsTitle') }}</h2></div><button class="refresh-button" :title="t('shares.refresh')" @click="loadGroups"><RefreshCw :size="17" :class="{ spin: groupsLoading }" /></button></div><div class="file-table-wrap share-management-table"><table class="file-table"><thead><tr><th>{{ t('shares.groupsTitle') }}</th><th>{{ t('shares.groupFiles') }}</th><th>{{ t('shares.expiresAt') }}</th><th>{{ t('shares.usage') }}</th><th>{{ t('shares.status') }}</th><th></th></tr></thead><tbody><tr v-for="group in groups" :key="group.id"><td><code class="share-token" :title="group.token">{{ group.token }}</code></td><td>{{ group.fileCount }}</td><td>{{ formatDate(group.expiresAt) }}<small class="share-remaining">{{ remainingLabel(group) }}</small></td><td>{{ group.downloadCount }} / {{ group.maxDownloads || t('shares.unlimited') }}</td><td><span class="status-label" :class="{ disabled: group.status !== 'active' }"><i></i>{{ statusLabel(group.status) }}</span></td><td><div class="row-actions"><button class="icon-button" :title="t('shares.groupEdit')" @click="openGroupEdit(group)"><Eye :size="16" /></button><button class="icon-button" :title="t('shares.copy')" @click="copyGroupUrl(group)"><Copy :size="16" /></button><button v-if="group.status !== 'revoked'" class="icon-button danger-icon" :title="t('shares.revoke')" @click="revokeGroup(group)"><Trash2 :size="16" /></button></div></td></tr></tbody></table><div v-if="!groups.length" class="empty-state"><Share2 :size="30" /><strong>{{ t('shares.groupEmpty') }}</strong><span>{{ t('shares.groupEmptyCopy') }}</span></div></div><div v-if="groupTotal > groupPageSize.value" class="pagination"><button class="secondary-button" :disabled="groupPage === 1" @click="groupPage--; loadGroups()">{{ t('common.previous') }}</button><span>{{ t('common.page', { page: groupPage }) }} / {{ groupTotalPages }}</span><button class="secondary-button" :disabled="groupPage * groupPageSize.value >= groupTotal" @click="groupPage++; loadGroups()">{{ t('common.next') }}</button><label class="page-size-label">{{ t('common.pageSize') }}<select v-model.number="groupPageSize" @change="changeGroupPageSize"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><template v-if="groupTotalPages > 7"><input v-model="groupPageInput" class="jump-input" type="number" min="1" :max="groupTotalPages" :placeholder="t('common.pageInput')" @keyup.enter="jumpGroupPage" /><button class="secondary-button" @click="jumpGroupPage">{{ t('common.jump') }}</button></template></div></section>
      <BrandFooter />
    </section>
    <div v-if="selected" class="modal-backdrop" @click.self="closeDetails"><section class="modal-panel share-details-panel" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">{{ t('shares.detailsEyebrow') }}</p><h2>{{ selected.fileName }}</h2></div><button class="icon-button" :title="t('common.close')" @click="closeDetails"><X :size="18" /></button></div><div class="share-detail-grid"><div><dt>{{ t('shares.token') }}</dt><dd class="detail-token">{{ selected.token }}</dd></div><div><dt>{{ t('shares.usage') }}</dt><dd>{{ selected.downloadCount }} / {{ selected.maxDownloads || t('shares.unlimited') }}</dd></div><div><dt>{{ t('shares.expiresAt') }}</dt><dd>{{ formatDate(selected.expiresAt) }}</dd></div><div><dt>{{ t('shares.remaining') }}</dt><dd>{{ remainingLabel(selected) }}</dd></div><div><dt>{{ t('shares.status') }}</dt><dd>{{ statusLabel(selected.status) }}</dd></div><div><dt>{{ t('shares.createdAt') }}</dt><dd>{{ formatDate(selected.createdAt) }}</dd></div></div><label class="form-label">{{ t('shares.link') }}<div class="share-url"><input :value="absoluteUrl(selected)" readonly /><button class="icon-button" :title="t('shares.copy')" @click="copyShare(selected)"><Copy :size="16" /></button></div></label><div class="share-manage-actions"><form @submit.prevent="extendShare"><label class="form-label">{{ t('shares.extendHours') }}<input v-model.number="extendHours" type="number" min="1" max="87600" required /></label><button class="secondary-button" :disabled="saving"><Clock3 :size="16" /> {{ t('shares.extend') }}</button></form><form @submit.prevent="increaseShare"><label class="form-label">{{ t('shares.increaseMax') }}<input v-model.number="increaseMax" type="number" min="0" max="100000" required /></label><button class="secondary-button" :disabled="saving"><Plus :size="16" /> {{ t('shares.increase') }}</button></form></div><p v-if="detailError" class="alert error">{{ detailError }}</p><section class="share-log-section"><div class="collection-section-header"><h3>{{ t('shares.downloadLogs') }}</h3><button class="icon-button" :title="t('shares.refreshLogs')" @click="loadShareLogs"><RefreshCw :size="16" :class="{ spin: logsLoading }" /></button></div><div v-if="logsLoading" class="empty-state compact-empty"><LoaderCircle :size="22" class="spin" /></div><div v-else-if="!shareLogs.length" class="transfers-empty">{{ t('shares.noLogs') }}</div><div v-else class="share-log-list"><div v-for="entry in shareLogs" :key="entry.id" class="share-log-row"><span>{{ formatDate(entry.createdAt) }}</span><span>{{ entry.ip || '-' }}</span><span class="result-label" :class="entry.result">{{ entry.result === 'success' ? t('logs.success') : t('logs.failure') }}</span><span>{{ reasonLabel(entry.reason) }}</span></div></div></section><div class="modal-actions"><button class="secondary-button" @click="openSharePage"><ExternalLink :size="16" /> {{ t('shares.open') }}</button><button v-if="selected.status !== 'revoked'" class="secondary-button danger-action" @click="revokeShare(selected)"><Trash2 :size="16" /> {{ t('shares.revoke') }}</button></div></section></div>
    <div v-if="groupAction" class="modal-backdrop" @click.self="groupAction = null"><section class="modal-panel" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">{{ groupAction.type === 'extend' ? t('shares.groupsExtend') : t('shares.groupsIncrease') }}</p><h2>{{ groupAction.type === 'extend' ? t('shares.groupExtendTitle') : t('shares.groupIncreaseTitle') }}</h2></div><button class="icon-button" :title="t('common.close')" @click="groupAction = null"><X :size="18" /></button></div><form @submit.prevent="submitGroupAction"><label class="form-label">{{ groupAction.type === 'extend' ? t('shares.extendHours') : t('shares.increaseMax') }}<input v-model.number="groupAction.value" type="number" :min="groupAction.type === 'extend' ? 1 : 0" :max="groupAction.type === 'extend' ? 87600 : 100000" required /></label><p class="muted">{{ groupAction.type === 'extend' ? t('shares.groupExtendHint') : t('shares.groupIncreaseHint') }}</p><p v-if="groupActionError" class="alert error">{{ groupActionError }}</p><div class="modal-actions"><button class="primary-button" :disabled="saving"><Clock3 v-if="groupAction.type === 'extend'" :size="16" /><Plus v-else :size="16" /> {{ groupAction.type === 'extend' ? t('shares.extend') : t('shares.increase') }}</button><button type="button" class="secondary-button" @click="groupAction = null">{{ t('common.cancel') }}</button></div></form></section></div>
    <div v-if="groupFiles" class="modal-backdrop" @click.self="groupFiles = null"><section class="modal-panel" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">{{ t('shares.groupsTitle') }}</p><h2>{{ t('shares.groupMembers') }}</h2></div><button class="icon-button" :title="t('common.close')" @click="groupFiles = null"><X :size="18" /></button></div><div v-if="groupFilesLoading" class="empty-state"><LoaderCircle :size="24" class="spin" /></div><div v-else-if="!groupFiles.items.length" class="empty-state">{{ t('shares.groupNoFiles') }}</div><div v-else class="group-files-list"><div v-for="item in groupFiles.items" :key="item.fileId" class="group-file-row"><strong :title="item.fileName">{{ item.fileName }}</strong><small>{{ formatBytes(item.size) }}</small></div></div></section></div>
    <div v-if="groupEdit" class="modal-backdrop" @click.self="groupEdit = null"><section class="modal-panel share-panel" role="dialog" aria-modal="true"><div class="panel-heading"><div><p class="eyebrow">{{ t('shares.groupEdit') }}</p><h2>{{ t('shares.groupEditTitle') }}</h2></div><button class="icon-button" :title="t('common.close')" @click="groupEdit = null"><X :size="18" /></button></div><form @submit.prevent="saveGroupEdit"><label class="form-label">{{ t('shares.groupExpiresAt') }}<input v-model="groupEdit.expiresAtLocal" type="datetime-local" required /></label><label class="form-label">{{ t('shares.groupMaxDownloads') }}<input v-model.number="groupEdit.maxDownloads" type="number" min="0" max="100000" required /></label><section class="group-member-section"><div class="panel-heading"><h3>{{ t('shares.groupMembers') }}</h3></div><div v-if="groupEdit.items.length" class="group-files-list"><div v-for="item in groupEdit.items" :key="item.fileId" class="group-file-row"><strong :title="item.fileName">{{ item.fileName }}</strong><small>{{ formatBytes(item.size) }}</small><button type="button" class="icon-button danger-icon" :title="t('shares.groupRemove')" @click="removeGroupMember(item)"><Trash2 :size="15" /></button></div></div><p v-else class="muted">{{ t('shares.groupNoFiles') }}</p><div class="group-add-row"><select v-model.number="groupEdit.pendingFileId" class="group-file-select" :aria-label="t('shares.groupSelectFile')"><option :value="0" disabled>{{ t('shares.groupSelectFile') }}</option><option v-for="file in groupAddCandidates" :key="file.id" :value="file.id">{{ file.name }}</option></select><button type="button" class="secondary-button" :disabled="!groupEdit.pendingFileId || groupEditSaving" @click="addGroupMember">{{ t('shares.groupAddFiles') }}</button></div></section><p v-if="groupEditError" class="alert error">{{ groupEditError }}</p><div class="modal-actions"><button class="primary-button" :disabled="groupEditSaving">{{ t('common.save') }}</button><button type="button" class="secondary-button" @click="groupEdit = null">{{ t('common.cancel') }}</button></div></form></section></div>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { api } from '../api'
import AuthenticatedTopbar from '../components/AuthenticatedTopbar.vue'
import BrandFooter from '../components/BrandFooter.vue'
import { currentLocale, t } from '../i18n'
import { Clock3, Copy, ExternalLink, Eye, LoaderCircle, Pencil, Plus, RefreshCw, Share2, Trash2, X } from 'lucide-vue-next'

const user = ref(JSON.parse(localStorage.getItem('filebox_user') || '{}'))
const shares = ref([]); const groups = ref([]); const groupsLoading = ref(false); const selected = ref(null); const shareLogs = ref([]); const loading = ref(false); const logsLoading = ref(false); const saving = ref(false); const error = ref(''); const detailError = ref(''); const notice = ref(''); const extendHours = ref(24); const increaseMax = ref(1); const groupAction = ref(null); const groupActionError = ref('')
const sharePage = ref(1); const shareTotal = ref(0); const sharePageSize = ref(Number(localStorage.getItem('filebox_pagesize_shares')) || 20); const sharePageInput = ref(''); const groupPage = ref(1); const groupTotal = ref(0); const groupPageSize = ref(Number(localStorage.getItem('filebox_pagesize_groups')) || 20); const groupPageInput = ref('')

// loadShares fetches the owner-scoped management list, including revoked history rows.
// loadShares 拉取当前用户可管理的分享列表，并保留已撤销历史行。
async function loadShares() { loading.value = true; error.value = ''; try { const body = await api(`/api/shares?page=${sharePage.value}&pageSize=${sharePageSize.value}`); shares.value = body.data.items || []; shareTotal.value = body.data.total || 0 } catch (err) { error.value = err.message } finally { loading.value = false } }
// loadGroups 拉取聚合分享（统一链接）列表（#7）。
// loadGroups fetches aggregate share groups (unified links) (#7).
async function loadGroups() { groupsLoading.value = true; error.value = ''; try { const body = await api(`/api/shares/groups?page=${groupPage.value}&pageSize=${groupPageSize.value}`); groups.value = body.data.items || []; groupTotal.value = body.data.total || 0 } catch (err) { error.value = err.message } finally { groupsLoading.value = false } }
// 分享/聚合分享分页辅助（v018 #7）：pageSize 选择 + 页码跳转，localStorage 记忆。
// Shares/groups pagination helpers (v018 #7): page-size selection and page jumping, persisted in localStorage.
const shareTotalPages = computed(() => Math.max(1, Math.ceil(shareTotal.value / sharePageSize.value)))
const groupTotalPages = computed(() => Math.max(1, Math.ceil(groupTotal.value / groupPageSize.value)))
function changeSharePageSize() { sharePage.value = 1; localStorage.setItem('filebox_pagesize_shares', String(sharePageSize.value)); loadShares() }
function changeGroupPageSize() { groupPage.value = 1; localStorage.setItem('filebox_pagesize_groups', String(groupPageSize.value)); loadGroups() }
function jumpSharePage() { const target = Number(sharePageInput.value); if (!target || target < 1 || target > shareTotalPages.value) { sharePageInput.value = ''; return } sharePage.value = target; sharePageInput.value = ''; loadShares() }
function jumpGroupPage() { const target = Number(groupPageInput.value); if (!target || target < 1 || target > groupTotalPages.value) { groupPageInput.value = ''; return } groupPage.value = target; groupPageInput.value = ''; loadGroups() }
async function revokeGroup(group) { if (!window.confirm(t('shares.confirmRevoke'))) return; try { await api(`/api/shared-groups/${encodeURIComponent(group.token)}`, { method: 'DELETE' }); notice.value = t('shares.revoked'); await loadGroups() } catch (err) { error.value = err.message } }
// 聚合分享成员文件弹窗与编辑弹窗（v018 #2）：眼睛查看文件范围；编辑可增删成员文件并改有效期/下载上限。
// Aggregate-share member-file dialog and edit dialog (v018 #2): the eye lists the file scope; the edit dialog
// adds/removes member files and changes the expiry and download limit.
const groupFiles = ref(null); const groupFilesLoading = ref(false)
const groupEdit = ref(null); const groupEditError = ref(''); const groupEditSaving = ref(false); const groupAddCandidates = ref([])
async function openGroupFiles(group) { groupFiles.value = { token: group.token, items: [] }; groupFilesLoading.value = true; try { const body = await api(`/api/shared-groups/${encodeURIComponent(group.token)}/files`); groupFiles.value.items = body.data.items || [] } catch (err) { error.value = err.message } finally { groupFilesLoading.value = false } }
function toLocalInputValue(value) { const date = new Date(value); if (Number.isNaN(date.getTime())) return ''; const pad = num => String(num).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}` }
async function openGroupEdit(group) { groupEditError.value = ''; groupEdit.value = null; try { const body = await api(`/api/shared-groups/${encodeURIComponent(group.token)}/files`); const items = body.data.items || []; groupEdit.value = { token: group.token, expiresAtLocal: toLocalInputValue(group.expiresAt), maxDownloads: group.maxDownloads || 0, items, pendingFileId: 0 }; const filesBody = await api('/api/files?page=1&pageSize=100'); const memberIds = new Set(items.map(item => item.fileId)); groupAddCandidates.value = (filesBody.data.items || []).filter(file => !memberIds.has(file.id)) } catch (err) { groupEditError.value = err.message } }
async function addGroupMember() { if (!groupEdit.value || !groupEdit.value.pendingFileId) return; groupEditSaving.value = true; groupEditError.value = ''; try { const body = await api(`/api/shared-groups/${encodeURIComponent(groupEdit.value.token)}/files`, { method: 'POST', body: JSON.stringify({ fileIds: [groupEdit.value.pendingFileId] }) }); const added = (body.data.items || [])[0]; const file = groupAddCandidates.value.find(item => item.id === added?.fileId); if (file) { groupEdit.value.items.push({ fileId: file.id, fileName: file.name, size: file.size }); groupAddCandidates.value = groupAddCandidates.value.filter(item => item.id !== file.id) } groupEdit.value.pendingFileId = 0; notice.value = t('shares.groupAdded') } catch (err) { groupEditError.value = err.message } finally { groupEditSaving.value = false } }
async function removeGroupMember(item) { if (!groupEdit.value) return; groupEditSaving.value = true; groupEditError.value = ''; try { await api(`/api/shared-groups/${encodeURIComponent(groupEdit.value.token)}/files/${item.fileId}`, { method: 'DELETE' }); groupEdit.value.items = groupEdit.value.items.filter(entry => entry.fileId !== item.fileId); const filesBody = await api('/api/files?page=1&pageSize=100'); const memberIds = new Set(groupEdit.value.items.map(entry => entry.fileId)); groupAddCandidates.value = (filesBody.data.items || []).filter(file => !memberIds.has(file.id)); notice.value = t('shares.groupRemoved') } catch (err) { groupEditError.value = err.message } finally { groupEditSaving.value = false } }
async function saveGroupEdit() { if (!groupEdit.value) return; groupEditSaving.value = true; groupEditError.value = ''; try { const body = await api(`/api/shared-groups/${encodeURIComponent(groupEdit.value.token)}`, { method: 'PUT', body: JSON.stringify({ expiresAt: new Date(groupEdit.value.expiresAtLocal).toISOString(), maxDownloads: groupEdit.value.maxDownloads }) }); notice.value = t('shares.groupUpdated'); const index = groups.value.findIndex(item => item.token === groupEdit.value.token); if (index >= 0) groups.value[index] = body.data; groupEdit.value = null } catch (err) { groupEditError.value = err.message } finally { groupEditSaving.value = false } }
function formatBytes(bytes = 0) { if (bytes < 1024) return `${bytes} B`; const units = ['KB', 'MB', 'GB', 'TB']; let value = bytes; let unit = -1; do { value /= 1024; unit++ } while (value >= 1024 && unit < units.length - 1); return `${value.toFixed(value >= 10 ? 0 : 1)} ${units[unit]}` }
// openGroupAction 打开聚合分享的延期/增次弹窗（#6），默认值参考单文件分享弹窗。
// openGroupAction opens the aggregate-share extend/increase dialog (#6) with defaults mirroring the single-share dialog.
function openGroupAction(group, type) { groupActionError.value = ''; groupAction.value = { type, group, value: type === 'extend' ? 24 : Math.max(1, (group.maxDownloads || 0) + 1) } }
// submitGroupAction 提交聚合分享延期（PUT .../extend）或增次（PUT .../increase），成功后就地更新行数据。
// submitGroupAction submits an aggregate-share extend (PUT .../extend) or increase (PUT .../increase) and updates the row in place.
async function submitGroupAction() { if (!groupAction.value) return; saving.value = true; groupActionError.value = ''; try { const action = groupAction.value; const body = await api(`/api/shared-groups/${encodeURIComponent(action.group.token)}/${action.type === 'extend' ? 'extend' : 'increase'}`, { method: 'PUT', body: JSON.stringify(action.type === 'extend' ? { expiresInHours: action.value } : { maxDownloads: action.value }) }); notice.value = action.type === 'extend' ? t('shares.extended') : t('shares.increased'); const index = groups.value.findIndex(item => item.token === action.group.token); if (index >= 0) groups.value[index] = body.data; groupAction.value = null } catch (err) { groupActionError.value = err.message } finally { saving.value = false } }
function groupUrl(group) { return group?.url ? new URL(group.url, window.location.origin).href : '' }
async function copyGroupUrl(group) { try { await navigator.clipboard.writeText(groupUrl(group)) } catch { const input = document.querySelector('.share-groups-panel input'); input?.select(); document.execCommand('copy') } notice.value = t('shares.copied') }
function openGroupPage(group) { window.open(groupUrl(group), '_blank', 'noopener') }
async function openDetails(item) { selected.value = item; detailError.value = ''; extendHours.value = 24; increaseMax.value = Math.max(1, item.maxDownloads + 1); try { selected.value = (await api(`/api/shares/${encodeURIComponent(item.token)}`)).data; await loadShareLogs() } catch (err) { detailError.value = err.message } }
function closeDetails() { selected.value = null; shareLogs.value = [] }
async function loadShareLogs() { if (!selected.value) return; logsLoading.value = true; try { shareLogs.value = (await api(`/api/shares/${encodeURIComponent(selected.value.token)}/logs?page=1&pageSize=100`)).data.items || [] } catch (err) { detailError.value = err.message } finally { logsLoading.value = false } }
async function extendShare() { if (!selected.value) return; saving.value = true; detailError.value = ''; try { const body = await api(`/api/shares/${encodeURIComponent(selected.value.token)}/extend`, { method: 'PUT', body: JSON.stringify({ expiresInHours: extendHours.value }) }); replaceShare(body.data); notice.value = t('shares.extended') } catch (err) { detailError.value = err.message } finally { saving.value = false } }
async function increaseShare() { if (!selected.value) return; saving.value = true; detailError.value = ''; try { const body = await api(`/api/shares/${encodeURIComponent(selected.value.token)}/increase`, { method: 'PUT', body: JSON.stringify({ maxDownloads: increaseMax.value }) }); replaceShare(body.data); notice.value = t('shares.increased') } catch (err) { detailError.value = err.message } finally { saving.value = false } }
async function revokeShare(item) { if (!window.confirm(t('shares.confirmRevoke'))) return; try { await api(`/api/shares/${encodeURIComponent(item.token)}`, { method: 'DELETE' }); notice.value = t('shares.revoked'); await loadShares(); if (selected.value?.token === item.token) { selected.value = shares.value.find(value => value.token === item.token) || null; if (selected.value) await loadShareLogs() } } catch (err) { detailError.value = err.message } }
function replaceShare(value) { selected.value = value; const index = shares.value.findIndex(item => item.token === value.token); if (index >= 0) shares.value[index] = value }
function absoluteUrl(item) { return item?.url ? new URL(item.url, window.location.origin).href : '' }
async function copyShare(item) { try { await navigator.clipboard.writeText(absoluteUrl(item)) } catch { const input = document.querySelector('.share-url input'); input?.select(); document.execCommand('copy') } notice.value = t('shares.copied') }
function openSharePage() { window.open(absoluteUrl(selected.value), '_blank', 'noopener') }
function statusLabel(status) { return t(`shares.status.${status}`) }
function remainingLabel(item) { if (item.status === 'revoked') return t('shares.revokedAt'); if (!item.remainingSeconds) return t('shares.expiredNow'); const hours = Math.floor(item.remainingSeconds / 3600); const minutes = Math.max(1, Math.floor(item.remainingSeconds / 60)); return t('shares.timeLeft', { value: hours ? `${hours}h` : `${minutes}m` }) }
function reasonLabel(value) { const keys = { share_not_found: 'logReason.shareNotFound', share_expired: 'logReason.shareExpired', share_revoked: 'logReason.shareRevoked', share_limit: 'logReason.shareLimit', share_denied: 'logReason.shareDenied' }; return keys[value] ? t(keys[value]) : value || '-' }
function formatDate(value) { return value ? new Date(value).toLocaleString(currentLocale.value === 'en' ? 'en-US' : currentLocale.value, { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '-' }
onMounted(() => { loadShares(); loadGroups() })
</script>
